(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var hdr = document.getElementById('hdr');
  function onScroll(){ if(window.scrollY > 12) hdr.classList.add('scrolled'); else hdr.classList.remove('scrolled'); }
  onScroll(); window.addEventListener('scroll', onScroll, {passive:true});

  /* header scroll-direction: down -> hide, up -> show (visual design untouched) */
  (function(){
    var prevY = window.scrollY || 0, ticking = false, THRESHOLD = 12, TOP_ZONE = 20;
    var mmEl = document.getElementById('mobileMenu');
    function update(){
      ticking = false;
      var y = window.scrollY || 0, delta = y - prevY;
      if (mmEl && mmEl.classList.contains('open')) { hdr.classList.remove('header-hidden'); prevY = y; return; }
      if (y <= TOP_ZONE) { hdr.classList.remove('header-hidden'); prevY = y; return; }
      if (Math.abs(delta) < THRESHOLD) return;          // ignore jitter
      if (delta > 0) hdr.classList.add('header-hidden'); // scrolling down
      else hdr.classList.remove('header-hidden');        // scrolling up
      prevY = y;
    }
    window.addEventListener('scroll', function(){ if(!ticking){ ticking = true; requestAnimationFrame(update); } }, {passive:true});
    update();
  })();

  var burger = document.getElementById('burger'), mm = document.getElementById('mobileMenu');
  burger.addEventListener('click', function(){ var o = mm.classList.toggle('open'); document.body.style.overflow = o?'hidden':''; if(o) hdr.classList.remove('header-hidden'); });
  mm.querySelectorAll('a').forEach(function(a){ a.addEventListener('click', function(){ mm.classList.remove('open'); document.body.style.overflow=''; }); });

  if(reduce){ document.querySelectorAll('.reveal').forEach(function(el){ el.classList.add('in'); }); }
  else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); } });
    }, {threshold:0.14, rootMargin:'0px 0px -8% 0px'});
    document.querySelectorAll('.reveal:not([data-load])').forEach(function(el){ io.observe(el); });
  }

  var dash = document.getElementById('dash');
  if(dash && !reduce){
    dash.style.opacity='0'; dash.style.transform='translateY(50px) scale(.97)';
    dash.style.transition='opacity .9s cubic-bezier(.16,1,.3,1), transform .9s cubic-bezier(.16,1,.3,1)';
  }
  function revealDash(){ if(dash){ dash.style.opacity='1'; dash.style.transform='none'; } drawFunnel(); drawTrend(); }
  window.addEventListener('load', function(){
    var loadEls = document.querySelectorAll('.reveal[data-load]');
    if(reduce){ loadEls.forEach(function(el){el.classList.add('in');}); setBarsInstant(); return; }
    loadEls.forEach(function(el){ el.classList.add('in'); });
    setTimeout(revealDash, 380);
  });

  function setBarsInstant(){ document.querySelectorAll('.fbar').forEach(function(b){ b.style.height=b.getAttribute('data-h')+'%'; }); }
  var funnelDrawn=false;
  function drawFunnel(){
    if(funnelDrawn) return; funnelDrawn=true;
    document.querySelectorAll('.fbar').forEach(function(b,i){ b.style.height='0%'; b.getBoundingClientRect();
      setTimeout(function(){ b.style.height=b.getAttribute('data-h')+'%'; }, 120+i*70); });
  }
  var trendDrawn=false;
  function drawTrend(){
    if(trendDrawn) return; trendDrawn=true; if(reduce) return;
    document.querySelectorAll('#trend .tline').forEach(function(p,i){
      var len=p.getTotalLength(); p.style.strokeDasharray=len; p.style.strokeDashoffset=len; p.getBoundingClientRect();
      p.style.transition='stroke-dashoffset 1.3s cubic-bezier(.16,1,.3,1) '+(i*0.16)+'s'; p.style.strokeDashoffset='0';
    });
  }

  var orbit = document.getElementById('orbit');
  if(orbit){
    var lines = orbit.querySelectorAll('.line'), nodes = orbit.querySelectorAll('.node');
    nodes.forEach(function(n,i){
      n.addEventListener('mouseenter', function(){ if(lines[i]){ lines[i].style.stroke='#1c71e7'; lines[i].style.opacity='1'; }});
      n.addEventListener('mouseleave', function(){ if(lines[i]){ lines[i].style.stroke=''; lines[i].style.opacity=''; }});
    });
  }
})();

(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var track=document.getElementById('tjTrack'); if(!track) return;
  var fill=document.getElementById('tjFill'), marker=document.getElementById('tjMarker');
  var steps=[].slice.call(track.querySelectorAll('.tj-step'));
  var nodes=steps.map(function(s){return s.querySelector('.tj-node');});
  if(reduce){ steps.forEach(function(s){s.classList.add('in');}); if(fill)fill.style.height='100%'; nodes.forEach(function(n){n&&n.classList.add('active');}); if(marker)marker.style.opacity='0'; return; }
  var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{threshold:.28,rootMargin:'0px 0px -8% 0px'});
  steps.forEach(function(s){io.observe(s);});
  var ticking=false;
  function clamp(v){return v<0?0:v>1?1:v;}
  function update(){
    ticking=false;
    var r=track.getBoundingClientRect(), vh=window.innerHeight;
    var startRef=vh*0.66, endRef=vh*0.44;
    var p=clamp((startRef - r.top)/(startRef - endRef + r.height));
    var spineLen=track.clientHeight-12;
    var y=6+p*spineLen;
    if(fill) fill.style.height=(p*100)+'%';
    if(marker){ marker.style.top=y+'px'; marker.style.opacity=(p>0.003 && p<0.999)?'1':(p>=0.999?'1':'0'); }
    for(var i=0;i<nodes.length;i++){ if(!nodes[i])continue;
      var np=steps[i].offsetTop+42;
      if(y>=np-6) nodes[i].classList.add('active'); else nodes[i].classList.remove('active');
    }
  }
  function onScroll(){ if(!ticking){ ticking=true; requestAnimationFrame(update); } }
  window.addEventListener('scroll', onScroll, {passive:true});
  window.addEventListener('resize', onScroll);
  update();
})();

(function(){
  var band=document.querySelector('.metrics'); if(band){
    var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var nums=[].slice.call(band.querySelectorAll('.mx .n'));
    function fmt(n){return n.toLocaleString('en-IN');}
    function render(el,val){var pre=el.getAttribute('data-pre')||'';var suf=el.getAttribute('data-suf')||'';el.innerHTML=(pre?'<span class="u">'+pre+'</span>':'')+fmt(val)+'<span class="u">'+suf+'</span>';}
    if(reduce){nums.forEach(function(el){render(el,+el.getAttribute('data-target'));});}
    else{
      nums.forEach(function(el){render(el,0);});
      var done=false;
      var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting&&!done){done=true;var t0=performance.now(),dur=1500;
        function tick(t){var p=Math.min((t-t0)/dur,1),e2=1-Math.pow(1-p,3);nums.forEach(function(el){render(el,Math.round(+el.getAttribute('data-target')*e2));});if(p<1)requestAnimationFrame(tick);}
        requestAnimationFrame(tick);io.disconnect();}});},{threshold:.4});
      io.observe(band);
    }
  }
  var bars=[].slice.call(document.querySelectorAll('.anbar[data-ah]'));
  if(bars.length){
    var reduce2=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if(reduce2){bars.forEach(function(b){b.style.height=b.getAttribute('data-ah');});}
    else{
      var io2=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.style.height=e.target.getAttribute('data-ah');io2.unobserve(e.target);}});},{threshold:.3});
      bars.forEach(function(b){b.style.height='0';io2.observe(b);});
    }
  }
})();

(function(){
  var space=document.getElementById('plxSpace'), sticky=document.getElementById('plxSticky'),
      track=document.getElementById('plxTrack'), ghost=document.getElementById('plxGhost'),
      fill=document.getElementById('plxFill'), dot=document.getElementById('plxDot');
  if(!space||!track) return;
  var cols=[].slice.call(track.querySelectorAll('.pcol'));
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var active=false, overflow=0, ticking=false;
  function enabled(){ return window.innerWidth>900 && !reduce; }
  function layout(){
    if(!enabled()){ space.style.height=''; track.style.transform=''; if(ghost)ghost.style.transform='translate3d(0,-50%,0)'; cols.forEach(function(c){c.classList.add('in');}); active=false; return; }
    active=true;
    overflow=Math.max(track.scrollWidth - sticky.clientWidth + 40, 0);
    space.style.height=(window.innerHeight + overflow)+'px';
    update();
  }
  function update(){
    ticking=false;
    if(!active) return;
    var top=space.getBoundingClientRect().top;
    var scrolled=Math.min(Math.max(-top,0),overflow);
    var p=overflow>0?scrolled/overflow:0;
    track.style.transform='translate3d('+(-scrolled)+'px,0,0)';
    if(ghost) ghost.style.transform='translate3d('+(-scrolled*0.42)+'px,-50%,0)';
    if(fill) fill.style.width=(p*100)+'%';
    if(dot) dot.style.left=(p*100)+'%';
    var vw=window.innerWidth;
    cols.forEach(function(c){ var l=c.getBoundingClientRect().left; if(l < vw*0.92) c.classList.add('in'); });
  }
  function onScroll(){ if(!ticking){ ticking=true; requestAnimationFrame(update); } }
  window.addEventListener('scroll', onScroll, {passive:true});
  var rt; window.addEventListener('resize', function(){ clearTimeout(rt); rt=setTimeout(layout,150); });
  window.addEventListener('load', layout);
  layout();
})();

