(function(){
  // ---------- Sankey funnel ----------
  var svg=document.getElementById('sankey'); 
  if(svg){
    var wrap=document.getElementById('sankeyWrap'), tip=document.getElementById('skTip');
    var sources=[
      {key:'walkin',label:'Walk-in',color:'#124a9e'},
      {key:'website',label:'Website',color:'#1c71e7'},
      {key:'chatbot',label:'Chatbot',color:'#6e9fe0'},
      {key:'acres',label:'99acres',color:'#a9c2ec'},
      {key:'others',label:'Others',color:'#C9C9C2'}
    ];
    var stages=[
      {name:'New Inquiry',vals:[78,132,96,62,44]},
      {name:'Contacted', vals:[54,92,64,44,32]},
      {name:'Qualified', vals:[40,70,50,32,22]},
      {name:'Site Visit',vals:[28,50,36,22,16]},
      {name:'Negotiation',vals:[18,32,22,14,10]},
      {name:'Booking',   vals:[11,20,13,8,6]}
