    var W=660,H=290,leftPad=6,rightPad=6,barW=22,padTop=26,padBottom=6;
    var n=stages.length, colGap=(W-barW-leftPad-rightPad)/(n-1), availH=H-padTop-padBottom;
    var totals=stages.map(function(s){return s.vals.reduce(function(a,b){return a+b;},0);});
    var maxT=Math.max.apply(null,totals);
    function sh(v){return v/maxT*availH;}
    var bands=[]; // bands[i][j]={y0,y1}
    for(var i=0;i<n;i++){var y=padTop;bands[i]=[];for(var j=0;j<sources.length;j++){var hh=sh(stages[i].vals[j]);bands[i][j]={y0:y,y1:y+hh};y+=hh;}}
    var NS='http://www.w3.org/2000/svg';
    function el(t,a){var e=document.createElementNS(NS,t);for(var k in a)e.setAttribute(k,a[k]);return e;}
    // ribbons (behind)
    for(var i=0;i<n-1;i++){
      var xR=leftPad+i*colGap+barW, xL=leftPad+(i+1)*colGap, mx=(xR+xL)/2;
      for(var j=0;j<sources.length;j++){
        var lt=bands[i][j].y0,lb=bands[i][j].y1,rt=bands[i+1][j].y0,rb=bands[i+1][j].y1;
