      wrap.classList.toggle('dim',!!key);
      svg.querySelectorAll('.sk-seg,.sk-rib').forEach(function(e){ e.classList.toggle('on', e.dataset.src===key); });
    }
    document.querySelectorAll('#skLegend .sk-lg').forEach(function(lg){
      lg.addEventListener('mouseenter',function(){setSrc(lg.dataset.src);});
      lg.addEventListener('mouseleave',function(){setSrc(null);});
    });
    // segment tooltip
    svg.querySelectorAll('.sk-seg').forEach(function(seg){
      seg.addEventListener('mousemove',function(ev){
        var rect=wrap.getBoundingClientRect();
        tip.style.left=(ev.clientX-rect.left)+'px'; tip.style.top=(ev.clientY-rect.top)+'px';
        tip.innerHTML='<b>'+seg.dataset.stage+'</b> &middot; '+seg.dataset.label+': '+seg.dataset.count;
        tip.classList.add('show');
        setSrc(seg.dataset.src);
      });
      seg.addEventListener('mouseleave',function(){ tip.classList.remove('show'); setSrc(null); });
    });
    // draw-in
    svg.querySelectorAll('.sk-rib').forEach(function(p,i){ p.style.opacity='0'; setTimeout(function(){p.style.opacity='0.24';}, 260+i*14); });
  }
  // ---------- clickable sidebar ----------
  var navItems=document.querySelectorAll('.bo-nav .bo-item');
