(function(){
  var NS='http://www.w3.org/2000/svg';
  function E(t,a){var e=document.createElementNS(NS,t);for(var k in a)e.setAttribute(k,a[k]);return e;}
  function rnd(seed){var s=seed*9301+49297;return function(){s=(s*9301+49297)%233280;return s/233280;};}
  function smooth(pts){ // catmull-rom -> bezier path
    if(pts.length<2)return '';
    var d='M'+pts[0][0]+','+pts[0][1];
    for(var i=0;i<pts.length-1;i++){
      var p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;
      var c1x=p1[0]+(p2[0]-p0[0])/6,c1y=p1[1]+(p2[1]-p0[1])/6;
      var c2x=p2[0]-(p3[0]-p1[0])/6,c2y=p2[1]-(p3[1]-p1[1])/6;
      d+=' C'+c1x+','+c1y+' '+c2x+','+c2y+' '+p2[0]+','+p2[1];
    }
    return d;
  }
  // ---- KPI sparklines ----
  document.querySelectorAll('.kpi-spark').forEach(function(svg){
    var color=svg.getAttribute('data-color'),seed=+svg.getAttribute('data-seed');
    var r=rnd(seed),W=220,H=42,n=24,pts=[],base=26;
    for(var i=0;i<n;i++){var v=base + Math.sin(i/2.5+seed)*5 + (r()-0.5)*10 - i*0.35; v=Math.max(6,Math.min(38,v)); pts.push([i/(n-1)*W, H-v]);}
    var id='sg'+seed;
    var grad=E('linearGradient',{id:id,x1:0,y1:0,x2:0,y2:1});
    grad.appendChild(E('stop',{offset:0,'stop-color':color,'stop-opacity':0.22}));
    grad.appendChild(E('stop',{offset:1,'stop-color':color,'stop-opacity':0}));
    var defs=E('defs',{});defs.appendChild(grad);svg.appendChild(defs);
    var line=smooth(pts);
    svg.appendChild(E('path',{d:line+' L'+W+','+H+' L0,'+H+' Z',fill:'url(#'+id+')'}));
    svg.appendChild(E('path',{d:line,fill:'none',stroke:color,'stroke-width':1.8,'stroke-linecap':'round','stroke-linejoin':'round'}));
  });
