  if(!space||!track) return;
  var mob=window.matchMedia('(max-width:900px)').matches || window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(mob) return;
  var cards=[].slice.call(track.children), dots=dotsWrap?[].slice.call(dotsWrap.children):[];
  var maxX=0;
  function calc(){ maxX=Math.max(0, track.scrollWidth - window.innerWidth + 120); }
  calc(); window.addEventListener('resize',function(){calc();upd();});
  var ticking=false;
  function upd(){ticking=false;
    var r=space.getBoundingClientRect();
    var total=space.offsetHeight-window.innerHeight;
    var p=total>0 ? (-r.top)/total : 0; p=p<0?0:p>1?1:p;
    track.style.transform='translate3d('+(-p*maxX).toFixed(1)+'px,0,0)';
    if(fill) fill.style.width=(p*100).toFixed(2)+'%';
