/* MediaTransitionSection driver — scroll progress -> scale/position/radius.
   Works with wheel, trackpad and touch (plain scroll listener, rAF-throttled).
   VIDEO PLACEHOLDER — FINAL VIDEO ASSET WILL BE PROVIDED (logic is media-agnostic). */
(function(){
  var space=document.getElementById('mediaSpace'), frame=document.getElementById('mediaFrame'),
      sticky=document.getElementById('mediaSticky'), fill=document.getElementById('mediaFill');
  if(!space||!frame) return;
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  var mob=window.matchMedia('(max-width:900px)').matches;
  var EXPAND=0.42;               // 0..EXPAND  : rise + grow to full screen
  var HOLD=0.82;                 // EXPAND..HOLD: full-screen moment (~2 scroll gestures)
                                 // HOLD..1     : controlled release
  function ease(t){return 1-Math.pow(1-t,3);}      // easeOutCubic
  function easeIO(t){return t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;}
  var ticking=false;

  function upd(){ticking=false;
    var total=space.offsetHeight-window.innerHeight;
    var p=total>0 ? (-space.getBoundingClientRect().top)/total : 0;
    p=p<0?0:p>1?1:p;

    // phase 1 — rise + expand to exactly full-screen
    var e=ease(Math.min(p/EXPAND,1));
    var startW=Math.min(1120,window.innerWidth*0.92), startH=startW*9/16;
    if(mob){startW=window.innerWidth*0.94;startH=startW*3/4;}
    var sx=window.innerWidth/startW, sy=window.innerHeight/startH;
    // Desktop: cover the viewport exactly. Mobile: fit width only (no oversized zoom / crop).
    var full=mob ? sx : Math.max(sx,sy);
    var s=1+(full-1)*e;                             // 1 -> full
    var base=mob?0.92:0.62;
    s=s*(base+(1-base)*e);                          // start slightly small, settle at cover
    var y=(1-e)*(mob?60:110);
    frame.style.setProperty('--ms',s.toFixed(4));
    frame.style.setProperty('--my',y.toFixed(1)+'px');
    frame.style.borderRadius=(22*(1-e)).toFixed(1)+'px';
    var pills=document.querySelector('.media-pills'); if(pills) pills.style.opacity=(1-Math.min(p/(EXPAND*0.55),1)).toFixed(3);
    var cap=frame.querySelector('.media-cap'); if(cap){cap.style.opacity=(e>0.85?1:0);cap.style.transform='scale('+(1/s).toFixed(4)+')';cap.style.transformOrigin='left bottom';}

    // phase 3 — controlled release (gentle settle back, next section slides over)
    if(p>HOLD){
      var r=easeIO((p-HOLD)/(1-HOLD));
      sticky.style.transform='translate3d(0,'+(-r*12).toFixed(1)+'vh,0)';
      sticky.style.opacity=(1-r*0.35).toFixed(3);
    }else{
      sticky.style.transform='none'; sticky.style.opacity=1;
    }
    // Header visibility: hidden only while the media is effectively full-screen.
    // (purely additive — does not alter the media interaction above)
    var hdrEl=document.getElementById('hdr');
    if(hdrEl){
      var fullscreenActive = p>EXPAND*0.92 && p<HOLD+ (1-HOLD)*0.25;
      hdrEl.classList.toggle('hdr-hidden', fullscreenActive);
    }

    // progress indicator visible during the full-screen hold
    var inHold=p>EXPAND*0.96 && p<HOLD;
    frame.style.setProperty('--prg',inHold?1:0);
    if(fill){var hp=Math.min(Math.max((p-EXPAND)/(HOLD-EXPAND),0),1);fill.style.width=(hp*100).toFixed(1)+'%';}
  }
  window.addEventListener('scroll',function(){if(!ticking){ticking=true;requestAnimationFrame(upd);}},{passive:true});
  window.addEventListener('resize',function(){mob=window.matchMedia('(max-width:900px)').matches;upd();});
  upd();
  // failsafe: never leave the header hidden once the media section is off-screen
  var ioHdr=new IntersectionObserver(function(es){es.forEach(function(e){
    if(!e.isIntersecting){var x=document.getElementById('hdr'); if(x) x.classList.remove('hdr-hidden');}
  });},{threshold:0});
  ioHdr.observe(space);
})();

