/* Motion system: single IntersectionObserver for reveals + staggered grids */
(function(){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('in');});
    return;
  }
  var groups=document.querySelectorAll('[data-stagger]');
  groups.forEach(function(g){g.classList.add('m-stagger');});
  var io=new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  },{threshold:.15,rootMargin:'0px 0px -8% 0px'});
  document.querySelectorAll('.reveal,[data-stagger]').forEach(function(el){
    if(!el.classList.contains('in')) io.observe(el);
  });
})();

/* ZEVRO preloader — real progress, guaranteed exit */
(function(){
  var zl=document.getElementById('zLoader'); if(!zl) return;
  var fill=document.getElementById('zlFill');
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  document.body.classList.add('zl-lock');

  var pct=0, done=false;
  function set(p){ pct=Math.max(pct,Math.min(p,100)); if(fill) fill.style.width=pct+'%'; }

  // progress from real image decoding
  var imgs=[].slice.call(document.images), total=imgs.length||1, loaded=0;
  function bump(){ loaded++; set(12+(loaded/total)*78); }
  imgs.forEach(function(im){
    if(im.complete) bump();
    else { im.addEventListener('load',bump,{once:true}); im.addEventListener('error',bump,{once:true}); }
  });
  set(12);
  var creep=setInterval(function(){ if(pct<88) set(pct+1); },135);

  function finish(){
    if(done) return; done=true;
    clearInterval(creep); set(100);
    setTimeout(function(){
      zl.classList.add('is-done');
      document.body.classList.remove('zl-lock');
      setTimeout(function(){ if(zl.parentNode) zl.parentNode.removeChild(zl); },1050);
      window.dispatchEvent(new Event('scroll'));   // let scroll-driven sections settle
    }, reduce?0:630);
  }
  window.addEventListener('load', function(){ setTimeout(finish, reduce?0:750); });
  setTimeout(finish, 6750);   // hard failsafe — never trap the user
})();
